CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','SUSPENDED','DELETED')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS wallets (id TEXT PRIMARY KEY, user_id TEXT NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE, currency TEXT NOT NULL DEFAULT 'CREDITS', balance BIGINT NOT NULL DEFAULT 0 CHECK (balance>=0), lifetime_earned BIGINT NOT NULL DEFAULT 0 CHECK (lifetime_earned>=0), version INT NOT NULL DEFAULT 0, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ledger_entries (id TEXT PRIMARY KEY, wallet_id TEXT NOT NULL REFERENCES wallets(id) ON DELETE CASCADE, type TEXT NOT NULL CHECK (type IN ('EARN','SPEND','REFUND')), amount_signed BIGINT NOT NULL CHECK (amount_signed!=0), idempotency_key TEXT NOT NULL, request_hash TEXT, policy_version TEXT, meta_json JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK ((type IN ('EARN','REFUND') AND amount_signed>0) OR (type='SPEND' AND amount_signed<0)), UNIQUE (wallet_id,idempotency_key));
CREATE INDEX IF NOT EXISTS idx_ledger_wallet ON ledger_entries(wallet_id);
CREATE INDEX IF NOT EXISTS idx_ledger_created ON ledger_entries(created_at);
CREATE TABLE IF NOT EXISTS reward_policies (id TEXT PRIMARY KEY, activity_type TEXT NOT NULL, credits_per_rep BIGINT NOT NULL CHECK (credits_per_rep>0), daily_cap INT NOT NULL CHECK (daily_cap>0), effective_at TIMESTAMPTZ NOT NULL, disabled_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS idx_reward_effective ON reward_policies(effective_at);
CREATE TABLE IF NOT EXISTS activity_sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, status TEXT NOT NULL CHECK (status IN ('CREATED','CALIBRATING','ACTIVE','SUBMITTED','VERIFYING','VERIFIED','REJECTED')), challenge_hash TEXT, install_id_hash TEXT, model_version TEXT, policy_version TEXT, duration_ms INT CHECK (duration_ms IS NULL OR duration_ms>=0), claimed_reps INT CHECK (claimed_reps IS NULL OR claimed_reps>=0), verified_reps INT CHECK (verified_reps IS NULL OR verified_reps>=0), evidence_hash TEXT, reject_reason TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), completed_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS idx_activity_user ON activity_sessions(user_id);
CREATE INDEX IF NOT EXISTS idx_activity_status ON activity_sessions(status);
CREATE TABLE IF NOT EXISTS provider_gateways (id TEXT PRIMARY KEY, key TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('ZEN','GO','ZEN_FREE','ZEN_PAID')), auth_scheme TEXT NOT NULL DEFAULT 'bearer', enabled BOOLEAN NOT NULL DEFAULT true, manifest_version INT NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS provider_endpoints (id TEXT PRIMARY KEY, gateway_id TEXT NOT NULL REFERENCES provider_gateways(id) ON DELETE RESTRICT, protocol TEXT NOT NULL CHECK (protocol IN ('responses','messages','chat_completions')), base_url TEXT NOT NULL, path_template TEXT NOT NULL, request_mapper_key TEXT NOT NULL, response_mapper_key TEXT NOT NULL, enabled BOOLEAN NOT NULL DEFAULT true);
CREATE INDEX IF NOT EXISTS idx_endpoint_gateway ON provider_endpoints(gateway_id);
CREATE TABLE IF NOT EXISTS model_catalog (logical_id TEXT PRIMARY KEY, provider_model_id TEXT NOT NULL, gateway_id TEXT NOT NULL REFERENCES provider_gateways(id) ON DELETE RESTRICT, endpoint_id TEXT NOT NULL REFERENCES provider_endpoints(id) ON DELETE RESTRICT, tier TEXT NOT NULL CHECK (tier IN ('FREE','STANDARD','PREMIUM')), credit_price BIGINT NOT NULL CHECK (credit_price>=0), limits_json JSONB NOT NULL DEFAULT '{}'::jsonb, capabilities_json JSONB NOT NULL DEFAULT '{}'::jsonb, enabled BOOLEAN NOT NULL DEFAULT true, manifest_version INT NOT NULL DEFAULT 1, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_model_tier ON model_catalog(tier);
CREATE INDEX IF NOT EXISTS idx_model_gateway ON model_catalog(gateway_id);
CREATE TABLE IF NOT EXISTS credential_deployments (id TEXT PRIMARY KEY, gateway_id TEXT NOT NULL REFERENCES provider_gateways(id) ON DELETE RESTRICT, pool_kind TEXT NOT NULL CHECK (pool_kind IN ('ZEN_FREE','GO','ZEN_PAID')), secret_ref TEXT NOT NULL, quota_scope_id TEXT NOT NULL, subscription_ref TEXT, promo_ends_at TIMESTAMPTZ, status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','DRAINING','DISABLED','COOLDOWN')), cooldown_until TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_deploy_gateway ON credential_deployments(gateway_id);
CREATE INDEX IF NOT EXISTS idx_deploy_pool ON credential_deployments(pool_kind);
CREATE INDEX IF NOT EXISTS idx_deploy_scope ON credential_deployments(quota_scope_id);
CREATE TABLE IF NOT EXISTS credential_usage_windows (quota_scope_id TEXT NOT NULL, window_type TEXT NOT NULL CHECK (window_type IN ('5H','WEEK','MONTH','DAY')), starts_at TIMESTAMPTZ NOT NULL, ends_at TIMESTAMPTZ NOT NULL, unit TEXT NOT NULL CHECK (unit IN ('USD_MICRO','REQUEST','INPUT_TOKEN','OUTPUT_TOKEN')), used_value BIGINT NOT NULL DEFAULT 0 CHECK (used_value>=0), limit_value BIGINT NOT NULL CHECK (limit_value>0), source TEXT NOT NULL DEFAULT 'provider', updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY (quota_scope_id,window_type), CHECK (ends_at>starts_at));
CREATE INDEX IF NOT EXISTS idx_usage_scope ON credential_usage_windows(quota_scope_id);
CREATE TABLE IF NOT EXISTS api_routes (route_key TEXT PRIMARY KEY, method TEXT NOT NULL CHECK (method IN ('GET','POST','PUT','PATCH','DELETE')), path_template TEXT NOT NULL, version TEXT NOT NULL DEFAULT 'v1', use_case_key TEXT NOT NULL, auth_policy_key TEXT NOT NULL, request_schema_key TEXT, response_schema_key TEXT, enabled BOOLEAN NOT NULL DEFAULT true, manifest_version INT NOT NULL DEFAULT 1, UNIQUE (method,path_template));
CREATE TABLE IF NOT EXISTS ui_navigation (route_key TEXT PRIMARY KEY REFERENCES api_routes(route_key) ON DELETE CASCADE, screen_key TEXT NOT NULL, label_key TEXT NOT NULL, icon_key TEXT, order_index INT NOT NULL, required_capability TEXT, feature_flag TEXT, enabled BOOLEAN NOT NULL DEFAULT true, manifest_version INT NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS design_tokens (theme TEXT NOT NULL, token_key TEXT NOT NULL, token_type TEXT NOT NULL CHECK (token_type IN ('color','dimension','fontFamily','fontWeight','duration','shadow','other')), token_value TEXT NOT NULL, contrast_pair TEXT, mode TEXT NOT NULL DEFAULT 'dark' CHECK (mode IN ('light','dark')), version INT NOT NULL DEFAULT 1, enabled BOOLEAN NOT NULL DEFAULT true, PRIMARY KEY (theme,token_key));
CREATE TABLE IF NOT EXISTS feature_flags (key TEXT PRIMARY KEY, default_value BOOLEAN NOT NULL DEFAULT false, rollout_json JSONB NOT NULL DEFAULT '{}'::jsonb, starts_at TIMESTAMPTZ, ends_at TIMESTAMPTZ, enabled BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS pool_policies (gateway_id TEXT NOT NULL REFERENCES provider_gateways(id) ON DELETE CASCADE, pool_kind TEXT NOT NULL CHECK (pool_kind IN ('ZEN_FREE','GO','ZEN_PAID')), min_active_deployments INT NOT NULL CHECK (min_active_deployments>=0), max_window_pct INT NOT NULL CHECK (max_window_pct>0 AND max_window_pct<=100), retry_policy_key TEXT, breaker_policy_key TEXT, enabled BOOLEAN NOT NULL DEFAULT true, PRIMARY KEY (gateway_id,pool_kind));
CREATE TABLE IF NOT EXISTS outbox_events (id TEXT PRIMARY KEY, event_type TEXT NOT NULL, aggregate_type TEXT NOT NULL, aggregate_id TEXT NOT NULL, payload_json JSONB NOT NULL, occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(), published_at TIMESTAMPTZ, attempts INT NOT NULL DEFAULT 0 CHECK (attempts>=0));
CREATE INDEX IF NOT EXISTS idx_outbox_unpublished ON outbox_events(published_at) WHERE published_at IS NULL;
CREATE TABLE IF NOT EXISTS seed_runs (id TEXT PRIMARY KEY, seed_version TEXT NOT NULL, checksum TEXT NOT NULL, manifest_version INT NOT NULL, actor TEXT NOT NULL DEFAULT 'system', status TEXT NOT NULL CHECK (status IN ('RUNNING','COMPLETED','FAILED')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), completed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS chat_quotes (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, logical_model_id TEXT NOT NULL REFERENCES model_catalog(logical_id) ON DELETE RESTRICT, credit_cost BIGINT NOT NULL CHECK (credit_cost>=0), max_output_tokens INT NOT NULL CHECK (max_output_tokens>0), request_hash TEXT NOT NULL, expires_at TIMESTAMPTZ NOT NULL, consumed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_quote_user ON chat_quotes(user_id);
CREATE TABLE IF NOT EXISTS chat_runs (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, quote_id TEXT REFERENCES chat_quotes(id) ON DELETE SET NULL, logical_model_id TEXT NOT NULL REFERENCES model_catalog(logical_id) ON DELETE RESTRICT, deployment_id TEXT REFERENCES credential_deployments(id) ON DELETE SET NULL, status TEXT NOT NULL CHECK (status IN ('PENDING','STREAMING','COMPLETED','FAILED','PARTIAL')), charged_credits BIGINT NOT NULL DEFAULT 0 CHECK (charged_credits>=0), provider_cost_usd_micro BIGINT NOT NULL DEFAULT 0 CHECK (provider_cost_usd_micro>=0), input_tokens INT NOT NULL DEFAULT 0 CHECK (input_tokens>=0), output_tokens INT NOT NULL DEFAULT 0 CHECK (output_tokens>=0), first_token_at TIMESTAMPTZ, completed_at TIMESTAMPTZ, idempotency_key TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (user_id,idempotency_key));
CREATE INDEX IF NOT EXISTS idx_run_user ON chat_runs(user_id);
CREATE INDEX IF NOT EXISTS idx_run_status ON chat_runs(status);
CREATE TABLE IF NOT EXISTS ad_events (id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id) ON DELETE SET NULL, placement TEXT NOT NULL, network_event_id TEXT UNIQUE, status TEXT NOT NULL CHECK (status IN ('ESTIMATED','FINALIZED','REJECTED')), estimated_revenue_micro BIGINT NOT NULL DEFAULT 0 CHECK (estimated_revenue_micro>=0), finalized_revenue_micro BIGINT CHECK (finalized_revenue_micro IS NULL OR finalized_revenue_micro>=0), occurred_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_ad_user ON ad_events(user_id);
